def fib():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

for i, x in enumerate(fib()):
    if i == 10:
        break
    print(x, end=" ")

def lines():
    for t in ["  Привет ", "", "МИР  ", "  ", "Да"]:
        yield t

def non_empty(src):
    for s in src:
        if s.strip():
            yield s

def cleaned(src):
    for s in src:
        yield s.strip().lower()

print(list(cleaned(non_empty(lines()))))

def flat(items):
    for x in items:
        if isinstance(x, list):
            yield from flat(x)
        else:
            yield x

print(list(flat([1, [2, [3, 4]], 5])))

from contextlib import contextmanager

@contextmanager
def tag(name):
    print(f"<{name}>")
    try:
        yield
    finally:
        print(f"</{name}>")

with tag("p"):
    print("текст")

def chunks(items, n):
    for i in range(0, len(items), n):
        yield items[i:i + n]

def pairs(items):
    return zip(items, items[1:])

print(list(chunks([1, 2, 3, 4, 5], 2)))
print(list(pairs([1, 2, 3, 4])))
